        "isGestureInsetBottomIgnored": true,
        "setFitToContents": true,
        "isHideable": true,
        "heightPercentage": 0.8
    };
    java.showBrowser(url, htmlContent, "window.java=java;", JSON.stringify(browserConfig));
}

function createBubble(number, url, bubble) {
    var num = number > 99 ? "99+" : number.toString();
    bubble = bubble.replace('$num', num);
    var encodedBubble = this.java.base64Encode(bubble);
    encodedBubble = 'data:image/svg+xml;base64,' + encodedBubble + ',{"click":"showPara(\'' + (mw + url) + '\' )","style":"text"}';
    return '<img src="' + encodedBubble + '">';
}

function showChapter(url) {
    var java = this.java;
    var cache = this.cache;
    var date = new Date().toLocaleDateString();
    var cacheKey = date + "end";
    var htmlContent = cache.get(cacheKey);
    if (!htmlContent || String(htmlContent).indexOf("id=") === -1) {
        htmlContent = java.ajax(url);
        cache.put(cacheKey, htmlContent);
    }
    var browserConfig = {
        "expandedCornersRadius": 20,
        "dismissOnTouchOutside": true,
        "isDraggable": true,
        "shouldDimBackground": true,
        "backgroundDimAmount": 0.5,
