@js:
(function () {
    var text = String(result || ''), doc = org.jsoup.Jsoup.parse(text);
    var visible = String(doc.select('#chapter_content').text());
    if (visible.length > 80 && visible.indexOf('\u6b63\u5728\u52a0\u8f7d') < 0) return visible;
    var id = text.match(/ajaxGetContent\s*\(\s*["'](\d+)["']/);
    var request = text.match(/\$\.get\s*\(\s*["']([^"']+_getcontent\.php\?id=)["']\s*\+\s*chapid\s*\+\s*["']([^"']*)["']/);
    if (!id || !request) throw new Error('No public chapter request found');
    var url = String(new Packages.java.net.URL(new Packages.java.net.URL(String(baseUrl)), request[1] + id[1] + request[2]));
    var content = String(java.ajax(url + ',' + JSON.stringify({headers: {Referer: String(baseUrl), 'X-Requested-With': 'XMLHttpRequest'}})));
    if (!content || content === 'readerror' || /<html|<form|Just a moment/i.test(content))
        throw new Error('Chapter content unavailable');
    return content;
})()

