}

function reg() {
    java.startBrowser("https://alicesw.org/user/user/reg.html", "注册账号");
}

function login() {}

function Login() {
    cookie.removeCookie(ul);
    const loginul = "https://alicesw.org/user/user/login.html"
    const codeul = "https://alicesw.org/user/user/verify.html"

    const na = result['用户名/邮箱'];
    const pa = result['密码']
    if (String(na && pa)) {
        let phpid = java.get(codeul, {}).header("set-cookies");
        java.log(phpid);
        let code = java.getVerificationCode(codeul);
        let body = `username=${na}&password=${pa}&code=${code}`
        let cook = java.post(loginul, body, {
            "x-requested-with": "XMLHttpRequest",
            "Cookie": phpid
        });
        let ck = String(cook.cookies()).replace(/[{}]/g, "").replace(",", "; ");
        //java.log(String(ck))
        let headers = JSON.stringify({
            "Cookie": ck
        });
        let usercode = JSON.parse(cook.body()).msg
        java.toast(usercode);
        if (ck) {
            source.putLoginHeader(headers);
            cookie.replaceCookie(ul, ck);
        } else {
            source.removeLoginHeader();
            cookie.removeCookie(ul)
        }
    }
}

function out() {
    source.removeLoginHeader();
    cookie.removeCookie(ul);
    java.toast("已退出登录状态");
}

function show() {
    let jc = source.getLoginHeaderMap();
    let us, id, codes
    if (jc) {
        let info = jc.get("Cookie").match(/%22%3A%22(\d+?)%22%2C%22username%22%3A%22(.*?)%22%7D/)
        us = info[2];
        id = info[1];
        codes = "✔️已登录";
    } else {
