function AFBook(ta) {
    let info = result['书籍ID']
    if (String(info) && source.getLoginHeaderMap()) {
        let bookid = info
        java.log(bookid);
        try {
            let ul
            if (ta) {
                ul = `https://alicesw.org/user/bookshelf/add?novel_id=${bookid}`
            } else {

                let src = ""
                for (page = 1;; page++) {
                    let sr = java.ajax(`https://alicesw.org/user/bookshelf?page=${page}`);
                    if (!/书架空空如也/.test(sr)) {
                        src += sr + "\n";
                    } else {
                        break;
                    }
                }
                //java.log("书籍在书架第"+page+"页");
                let booklist = src.match(/\/novel\/\d+\.html/g);
                let dfid = src.match(/\/user\/bookshelf\/del[^"]+/g);
                for (i in booklist) {
                    if (booklist[i].includes(bookid)) {
                        ra = dfid[i];
                        break;
                    }
                }
                ul = source.key + ra;
            }
            let msg = java.get(ul, {
                "x-requested-with": "XMLHttpRequest"
            });
            let point = JSON.parse(msg.body()).msg
            java.toast(point);
        } catch(error) {
            //java.log(error);
            java.toast('无效操作');
        }
    } else if(!String(info)) {
        java.toast("\n未填入书籍id，请进书籍详情页，或者手动填写。");
   } else if(!source.getLoginHeaderMap()) {
    	java.toast("未登录，请登录后使用");
  }
}

function BookShelf() {
    if (source.getLoginHeaderMap()) {
        java.startBrowser("https://alicesw.org/user/bookshelf/", "书架");
    } else {
        java.toast("未登录，请登录后再使用此功能。");
    }
}

