    java.startBrowser("data:text/html;base64," + htm, "书架");
}
var sgv = source.getVariable();
var sg = source.get("list");
//放置书籍信息至书源变量
function bookinto() {
    if (String(sg)) {
        let sgv1 = JSON.parse(sgv);
        let sg1 = JSON.parse(sg);
        let exists = sgv1.some(item => {
            return Number(item.ID) === Number(sg1.ID);
        });
        if (!exists) {
            sgv1.push(sg1);
            source.setVariable(JSON.stringify(sgv1, null, "\t"));
            java.toast("添加成功");
        } else {
            java.toast("书籍已存入本地书架中");
        }
    } else {
        java.toast('🚫请进入书籍详情页后操作，或者刷新试试')
    }
}

function bookmove(a) {
    try {
        let sgv1 = JSON.parse(sgv);
        let sg1 = JSON.parse(sg);
        if (a == "all") {
            source.put("list", '')
            java.log(source.get("list"));
            source.setVariable("");
            java.toast('已清空本地书架');
        } else {
            let index = sgv1.findIndex(item => Number(item.ID) === Number(sg1.ID));
            if (index != -1) {
                sgv1.splice(index, 1);
                source.setVariable(JSON.stringify(sgv1, null, "\t"));
                java.toast(`已从本地删除该书籍。\n书籍ID：${sg1.ID}`);
            } else {
                java.toast('书籍不在本地书架中')
            }
        }
